/** Пропускает только чтение (list_/get_). Всё остальное — блок + запись в список, который тест проверяет пустым. */
async function guardWrites(page: Page): Promise<string[]> {
  const blocked: string[] = [];
  await page.route(/\/rest\/v1\/rpc\//, (route) => {
    const name = route.request().url().split('/rpc/')[1]?.split('?')[0] ?? '';
    if (/^(admin_)?(list|get)_/.test(name)) return route.continue();
    blocked.push(name);
    return route.abort();
  });
  return blocked;
}

const mockList = (page: Page, rows: unknown[]) =>
  page.route(LIST_RPC, (r) => r.fulfill({ status: 200, contentType: 'application/json', body: JSON.stringify(rows) }));

/** Положение значка внутри кнопки: отступ слева и справа от левого края кнопки, высота кнопки. */
async function iconBox(button: ReturnType<Page['locator']>) {
  await expect(button.locator('img')).toBeVisible();
  return button.evaluate((b) => {
    const img = b.querySelector('img') as HTMLElement;
    const rb = b.getBoundingClientRect();
    const ri = img.getBoundingClientRect();
    return {
      h: Math.round(rb.height),
      left: +(ri.left - rb.left).toFixed(1),
      right: +(ri.right - rb.left).toFixed(1),
      iconCenter: ri.left + ri.width / 2 - rb.left,
      btnCenter: rb.width / 2,
    };
  });
}

function expectIconLeft(box: Awaited<ReturnType<typeof iconBox>>, left: number, h: number, what: string) {
  // Источник: реджект 2, п.1 — иконка слева (Figma 822:2567 / 822:2588 / 822:2683); допуск ±2 px на шрифт.
  expect(box.h, `высота «${what}»`).toBe(h);
  expect(box.left, `отступ значка слева «${what}»`).toBeGreaterThanOrEqual(left - 2);
  expect(box.left, `отступ значка слева «${what}»`).toBeLessThanOrEqual(left + 2);
  expect(box.right - box.left, `ширина значка «${what}»`).toBeCloseTo(20, 0);
  expect(box.iconCenter, `значок «${what}» левее центра кнопки`).toBeLessThan(box.btnCenter);
}

async function noHorizontalScroll(page: Page, where: string) {
  const [sw, iw] = await page.evaluate(() => [document.documentElement.scrollWidth, window.innerWidth]);
  expect(sw, `горизонтальная прокрутка (${where})`).toBeLessThanOrEqual(iw);
}

test.describe(`Админка — заявки на информацию и удаление (${HASH})`, () => {
  test(`значок слева в «קליטת בקשה» и в «לבקשות שטופלו…» (пустое «פתוחות»), 1440 и 390 @desktop @prod-safe ${HASH}`, async ({ page }) => {
    const blocked = await guardWrites(page);
    await mockList(page, []);
    for (const vp of [WIDE, NARROW]) {
      await page.setViewportSize(vp);
      await page.goto(URL_PATH);
      await expect(page.getByTestId('data-requests-empty')).toBeVisible();

      const intake = page.getByRole('button', { name: 'קליטת בקשה' }).first();
      expectIconLeft(await iconBox(intake), 25, 44, `קליטת בקשה @${vp.width}`);

      const toHandled = page.getByRole('button', { name: 'לבקשות שטופלו ב-3 החודשים האחרונים' });
      expectIconLeft(await iconBox(toHandled), 17, 40, `לבקשות שטופלו @${vp.width}`);

      await noHorizontalScroll(page, `empty @${vp.width}`);
    }
    expect(blocked, 'неожиданные запросы на запись').toEqual([]);
  });

  test(`ошибка загрузки: «ניסיון נוסף» со стрелкой слева, без счётчиков, 1440 и 390 @desktop @prod-safe ${HASH}`, async ({ page }) => {
    const blocked = await guardWrites(page);
    await page.route(LIST_RPC, (r) => r.abort()); // имитация сбоя списка
    for (const vp of [WIDE, NARROW]) {
      await page.setViewportSize(vp);
      await page.goto(URL_PATH);
      const retry = page.getByRole('button', { name: 'ניסיון נוסף' });
      await expect(retry).toBeVisible({ timeout: 30_000 });
      await expect(page.getByText('לא הצלחנו לטעון את הבקשות')).toBeVisible();
      expectIconLeft(await iconBox(retry), 17, 40, `ניסיון נוסף @${vp.width}`);

      // Источник: реджект 1, п.3 / Figma 822:2603 — при сбое нет счётчиков 0/0/0.
      await expect(page.getByTestId('data-request-views'), `счётчики при ошибке @${vp.width}`).not.toContainText(/\d/);
      await noHorizontalScroll(page, `error @${vp.width}`);
    }
    expect(blocked, 'неожиданные запросы на запись').toEqual([]);
  });

  test(`загрузка: «טוען את הבקשות…» без счётчиков, затем список @desktop @prod-safe ${HASH}`, async ({ page }) => {
    const blocked = await guardWrites(page);
    let release!: () => void;
    const gate = new Promise<void>((resolve) => (release = resolve));
    await page.route(LIST_RPC, async (r) => {
      await gate;
      await r.fulfill({ status: 200, contentType: 'application/json', body: '[]' });
    });
    await page.goto(URL_PATH);
    // Источник: реджект 1, п.3 / Figma 872:5561 — загрузка без счётчиков.
    await expect(page.getByText('טוען את הבקשות…')).toBeVisible();
    await expect(page.getByTestId('data-request-views')).not.toContainText(/\d/);
    release();
    await expect(page.getByTestId('data-requests-empty')).toBeVisible();
    await expect(page.getByTestId('data-request-views')).toContainText('0');
    expect(blocked, 'неожиданные запросы на запись').toEqual([]);
  });

  test(`окно «השלמת בקשת המחיקה»: eyebrow rgb(233,150,127), «השלמת הבקשה» disabled до галочки, пустое «תיעוד הטיפול» блокирует, ничего не отправляется @desktop @prod-safe ${HASH}`, async ({ page }) => {
    const blocked = await guardWrites(page);
    await mockList(page, [MOCK_DELETION]);
    await page.goto(URL_PATH);
    await expect(page.getByTestId('data-request-row')).toHaveCount(1);
    await page.getByTestId('row-menu').click();
    await page.getByRole('menuitem', { name: 'השלמת הבקשה' }).click();

    const dialog = page.getByTestId('data-request-dialog');
    await expect(dialog).toBeVisible();
    await expect(dialog.getByRole('heading', { name: 'השלמת בקשת המחיקה' })).toBeVisible();

    // Источник: реджект 2, п.2 / Figma 823:3093 — eyebrow цвета --nd-alert #E9967F.
    const eyebrow = dialog.getByText('מחיקה · מנהל/ת מערכת בלבד');
    await expect(eyebrow).toHaveCSS('color', 'rgb(233, 150, 127)');

    // Источник: реджект 1, п.4 + реджект 2, п.3 / Figma 823:3099 — до галочки кнопка disabled, тёмная, светлый текст, 220 px.
    const complete = dialog.getByRole('button', { name: 'השלמת הבקשה' });
    await expect(complete).toBeDisabled();
    await expect(complete).toHaveCSS('background-color', 'rgba(255, 255, 255, 0.1)');
    await expect(complete).toHaveCSS('color', /^(color\(srgb 1 1 1 \/ 0\.7\d*\)|rgba\(255, 255, 255, 0\.7\d*\))$/);
    const width = (await complete.boundingBox())!.width;
    expect(Math.abs(width - 220), `ширина кнопки ${width}`).toBeLessThanOrEqual(2);

    // После галочки — активна, текст тёмный на светлой кнопке.
    await dialog.getByRole('checkbox', { name: /אני מאשר\/ת את מחיקת ההקלטה/ }).check();
    await expect(complete).toBeEnabled();
    await expect(complete).toHaveCSS('color', 'rgb(10, 5, 3)');

    // Попутная находка 04.11, подтверждена 17.11: пустое «תיעוד הטיפול (חובה)» не даёт завершить.
    await complete.click();
    await expect(dialog.getByText('יש לתעד את אופן הטיפול בבקשה')).toBeVisible();
    await expect(dialog, 'окно осталось открытым').toBeVisible();
    expect(blocked, 'при пустом תיעוד не должно быть запроса на завершение').toEqual([]);

    // Закрываем без завершения.
    await dialog.getByRole('button', { name: 'ביטול' }).click();
    await expect(dialog).toBeHidden();
    expect(blocked, 'неожиданные запросы на запись').toEqual([]);
  });

  test(`панель «קליטת בקשה» закрывается ×, Esc и «ביטול», заявка не создаётся @desktop @prod-safe ${HASH}`, async ({ page }) => {
    const blocked = await guardWrites(page);
    await mockList(page, []);
    await page.goto(URL_PATH);
    await expect(page.getByTestId('data-requests-empty')).toBeVisible();

    const panel = page.getByTestId('data-request-intake');
    const open = async () => {
      await page.getByRole('button', { name: 'קליטת בקשה' }).first().click();
      await expect(panel).toBeVisible();
      await expect(panel.getByText('סוג הבקשה').first()).toBeVisible();
    };

    // Источник: реджект 1, п.1 / Figma 843:3162 — выезжающая панель, а не встроенная форма.
    await open();
    await panel.getByRole('button', { name: 'סגירה' }).click();
    await expect(panel, 'закрытие ×').toBeHidden();

    await open();
    await page.keyboard.press('Escape');
    await expect(panel, 'закрытие Esc').toBeHidden();

    await open();
    await panel.getByRole('button', { name: 'ביטול' }).click();
    await expect(panel, 'закрытие «ביטול»').toBeHidden();

    await expect(page.getByTestId('data-requests-empty')).toBeVisible();
    expect(blocked, 'закрытие панели ничего не создаёт').toEqual([]);
  });
});
